// Some portions generated by Claude
import { useMemo, useState, type CSSProperties } from "react";
import type { LoadBatch, ViewMode } from "./explorer-types.ts";
import { unorderedPairKey } from "./graph-geometry.ts";
import { mapFrame, parseGraphDate, placesOf } from "./graph-literals.ts";
import { histogram, numericSeriesOf, predicateChartOf } from "./chart-data.ts";
import { compactTerm, termCode } from "./graph-terms.ts";
import type { Graph, GraphEdge, GraphNode } from "./graph-types.ts";
import { nodeVisual, primaryNodeType } from "./graph-visuals.ts";
import { Icon } from "./icons.tsx";

export type DataViewMode = Exclude<ViewMode, "graph">;

export type DataViewsProps = {
  viewMode: DataViewMode;
  graph: Graph;
  /** The nodes the views list: the selection, or every selectable node. */
  viewNodes: readonly GraphNode[];
  selectedCount: number;
  nodeById: ReadonlyMap<string, GraphNode>;
  batchById: ReadonlyMap<string, LoadBatch>;
  onUseVisualQuery: () => void;
  onShowInGraph: (nodeId: string) => void;
  onSelectNodes: (nodeIds: string[]) => void;
};

/** Dated statements (the object is a date literal), oldest first. */
export function timelineEventsOf(edges: readonly GraphEdge[], nodeById: ReadonlyMap<string, GraphNode>) {
  return edges
    .flatMap((edge) => {
      const target = nodeById.get(edge.target);
      const source = nodeById.get(edge.source);
      const date = target ? parseGraphDate(target) : null;
      return date && source && target ? [{ edge, source, target, date }] : [];
    })
    .sort((left, right) => left.date.getTime() - right.date.getTime());
}

/** OpenStreetMap's embeddable map framed around the places, with a marker on the first (it shows only one). */
function mapEmbedUrl(places: ReturnType<typeof placesOf>) {
  const { west, south, east, north } = mapFrame(places);
  const bbox = [west, south, east, north].map(encodeURIComponent).join("%2C");
  return `https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik&marker=${places[0].latitude}%2C${places[0].longitude}`;
}

/**
 * The non-graph views of the loaded data: Triples, Cards, Matrix, Timeline, Map and Chart. Their derived data is
 * computed here, so it is only computed while one of them is shown.
 */
const PREDICATE_CHART = "predicates";
/** Statements the Triples view lists at a time. */
const TABLE_PAGE = 500;

export function DataViews({
  viewMode,
  graph,
  viewNodes,
  selectedCount,
  nodeById,
  batchById,
  onUseVisualQuery,
  onShowInGraph,
  onSelectNodes,
}: DataViewsProps) {
  const [tableSearch, setTableSearch] = useState("");
  // A large graph has hundreds of thousands of statements; the table lists them a page at a time.
  const [tableLimit, setTableLimit] = useState(TABLE_PAGE);
  // With nodes selected, every view shows what concerns them (as the header says); otherwise the whole loaded graph.
  const selectedIds = useMemo(() => (selectedCount ? new Set(viewNodes.map((node) => node.id)) : null), [selectedCount, viewNodes]);
  const touchesSelection = (...ids: string[]) => !selectedIds || ids.some((id) => selectedIds.has(id));
  const scopedEdges = useMemo(
    () => (selectedIds ? graph.edges.filter((edge) => selectedIds.has(edge.source) || selectedIds.has(edge.target)) : graph.edges),
    [graph.edges, selectedIds],
  );
  const tableRows = useMemo(() => {
    if (viewMode !== "table") return [];
    const searchTerm = tableSearch.trim().toLocaleLowerCase();
    const label = (id: string) => nodeById.get(id)?.label ?? compactTerm(id);
    const rows: Array<{ edge: GraphEdge; source?: GraphNode; target?: GraphNode; batch?: LoadBatch; statement?: string }> = [
      ...scopedEdges.map((edge) => ({
        edge,
        source: nodeById.get(edge.source),
        target: nodeById.get(edge.target),
        batch: edge.batchId ? batchById.get(edge.batchId) : undefined,
      })),
      // Statements about statements: the object is a triple term.
      ...(graph.statementLinks ?? [])
        .filter((link) => touchesSelection(link.source, link.subject, link.object))
        .map((link) => ({
          edge: { id: link.id, source: link.source, predicate: link.predicate, label: link.label, target: link.statementEdgeId },
          source: nodeById.get(link.source),
          statement: `<<( ${label(link.subject)} ${graph.edges.find((edge) => edge.id === link.statementEdgeId)?.label ?? compactTerm(link.statementPredicate)} ${label(link.object)} )>>`,
          batch: link.batchId ? batchById.get(link.batchId) : undefined,
        })),
    ];
    return rows.filter(({ edge, source, target, statement }) =>
      !searchTerm ||
      [source?.label, edge.label, target?.label, edge.predicate, statement]
        .some((value) => value?.toLocaleLowerCase().includes(searchTerm)),
    );
  }, [batchById, graph.edges, graph.statementLinks, nodeById, scopedEdges, tableSearch, viewMode]);
  const incidentEdges = useMemo(() => {
    const incident = new Map<string, GraphEdge[]>();
    if (viewMode !== "cards") return incident;
    graph.edges.forEach((edge) => {
      for (const id of edge.source === edge.target ? [edge.source] : [edge.source, edge.target]) {
        const list = incident.get(id);
        if (list) list.push(edge);
        else incident.set(id, [edge]);
      }
    });
    return incident;
  }, [graph.edges, viewMode]);
  const matrixNodes = useMemo(() => viewNodes.slice(0, 36), [viewNodes]);
  const pairEdges = useMemo(() => {
    const pairs = new Map<string, GraphEdge[]>();
    if (viewMode !== "matrix") return pairs;
    graph.edges.forEach((edge) => {
      const key = unorderedPairKey(edge.source, edge.target);
      const list = pairs.get(key);
      if (list) list.push(edge);
      else pairs.set(key, [edge]);
    });
    return pairs;
  }, [graph.edges, viewMode]);
  const timelineEvents = useMemo(
    () =>
      viewMode === "timeline"
        ? timelineEventsOf(graph.edges, nodeById).filter((event) => touchesSelection(event.source.id, event.target.id))
        : [],
    [graph.edges, nodeById, selectedIds, viewMode],
  );
  const places = useMemo(
    () => (viewMode === "map" ? placesOf(graph.edges, nodeById).filter((place) => touchesSelection(place.node.id)) : []),
    [graph.edges, nodeById, selectedIds, viewMode],
  );
  // The Chart shows one numeric predicate's distribution (the one with most values unless another is chosen), or how
  // often each predicate is used.
  const numericSeries = useMemo(
    () => (viewMode === "chart" ? numericSeriesOf(scopedEdges, nodeById) : []),
    [scopedEdges, nodeById, viewMode],
  );
  const [chosenSeries, setChosenSeries] = useState<string | null>(null);
  const series =
    chosenSeries === PREDICATE_CHART ? null : (numericSeries.find((entry) => entry.predicate === chosenSeries) ?? numericSeries[0] ?? null);
  const numericHistogram = useMemo(() => (series ? histogram(series.values) : []), [series]);
  const predicateChart = useMemo(() => (viewMode === "chart" ? predicateChartOf(scopedEdges) : []), [scopedEdges, viewMode]);

  return (
    <section className="data-view" aria-label={`${viewMode} view`}>
      <header className="data-view-header">
        <div className="data-view-title">
          <h3>
            {viewMode === "table"
              ? "Triples"
              : viewMode === "cards"
                ? "Resource cards"
                : viewMode === "matrix"
                  ? "Connection matrix"
                  : viewMode === "timeline"
                    ? "Timeline"
                    : viewMode === "map"
                      ? "Map"
                      : series
                        ? `Distribution of ${series.label}`
                        : "Relations by frequency"}
          </h3>
          <small>
            {selectedCount
              ? `${selectedCount} selected nodes`
              : "All loaded nodes"}
          </small>
        </div>
        <div className="data-view-actions">
          {viewMode === "table" && (
            <input
              type="search"
              aria-label="Search triples"
              value={tableSearch}
              onChange={(event) => {
                setTableSearch(event.target.value);
                setTableLimit(TABLE_PAGE);
              }}
              placeholder="Search triples"
            />
          )}
          <button
            className="workbench-action workbench-action--secondary"
            type="button"
            title="Open the query that matches the current filters in the query editor"
            onClick={onUseVisualQuery}
          >
            <Icon name="query" />
            Open as query
          </button>
        </div>
      </header>

      {viewMode === "table" && (
        <div className="table-shell">
          <table className="triple-table">
            <thead>
              <tr>
                <th>Subject</th>
                <th>Predicate</th>
                <th>Object</th>
                <th>Loaded by</th>
              </tr>
            </thead>
            <tbody>
              {!tableRows.length && <tr><td colSpan={4}><p className="view-note">{tableSearch ? "No triples match this search. Clear the search to see all loaded triples." : "No triples are loaded in this view yet."}</p></td></tr>}
              {tableRows.slice(0, tableLimit).map(({ edge, source, target, batch, statement }) => (
                <tr key={edge.id}>
                  <td>
                    <strong>{source?.label ?? compactTerm(edge.source)}</strong>
                    <code>{termCode(source, edge.source)}</code>
                  </td>
                  <td>
                    <strong>{edge.label}</strong>
                    <code>{compactTerm(edge.predicate, 42)}</code>
                  </td>
                  <td>
                    {statement ? (
                      <>
                        <strong>{statement}</strong>
                        <code>triple term</code>
                      </>
                    ) : (
                      <>
                        <strong>{target?.label ?? compactTerm(edge.target)}</strong>
                        <code>{termCode(target, edge.target)}</code>
                      </>
                    )}
                  </td>
                  <td>
                    {batch?.label ?? "Imported"}
                    <small>
                      {batch
                        ? new Date(batch.loadedAt).toLocaleString()
                        : "Unknown source"}
                    </small>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {tableRows.length > tableLimit ? (
            <p className="view-note table-more">
              Showing {tableLimit.toLocaleString()} of {tableRows.length.toLocaleString()} statements.{" "}
              <button type="button" className="filter-more" onClick={() => setTableLimit((limit) => limit + TABLE_PAGE)}>
                Show {Math.min(TABLE_PAGE, tableRows.length - tableLimit).toLocaleString()} more
              </button>
            </p>
          ) : null}
        </div>
      )}

      {viewMode === "cards" && (
        <div className="entity-card-grid">
          {viewNodes.slice(0, 80).map((node) => {
            const incident = incidentEdges.get(node.id) ?? [];
            return (
              <article
                className="entity-card"
                key={node.id}
                style={
                  {
                    "--card-accent": nodeVisual(node).stroke,
                  } as CSSProperties
                }
              >
                <header>
                  <span>
                    {node.kind === "iri"
                      ? primaryNodeType(node)?.label ?? "Resource"
                      : node.kind === "literal"
                        ? "Value"
                        : "Blank node"}
                  </span>
                  {node.pinned && <i>PINNED</i>}
                </header>
                <h4>{node.kind === "literal" ? node.termValue ?? node.label : node.label}</h4>
                {node.kind === "iri" ? <code>{compactTerm(node.id, 48)}</code> : null}
                <dl>
                  {incident.slice(0, 6).map((edge) => {
                    const outgoing = edge.source === node.id;
                    const other = nodeById.get(
                      outgoing ? edge.target : edge.source,
                    );
                    return (
                      <div key={edge.id}>
                        <dt>
                          {outgoing ? "→ " : "← "}
                          {edge.label}
                        </dt>
                        <dd>{other?.label ?? "Unknown node"}</dd>
                      </div>
                    );
                  })}
                </dl>
                <button
                  className="workbench-action workbench-action--secondary"
                  type="button"
                  onClick={() => onShowInGraph(node.id)}
                >
                  Show in graph
                </button>
              </article>
            );
          })}
        </div>
      )}

      {viewMode === "matrix" && (
        <div className="matrix-shell">
          <p className="view-note">
            Showing {matrixNodes.length} of {viewNodes.length} nodes. Select nodes in the graph to choose which ones.
          </p>
          <div
            className="matrix-grid"
            style={{
              gridTemplateColumns: `180px repeat(${matrixNodes.length}, 36px)`,
            }}
            role="grid"
            aria-label="Adjacency matrix"
          >
            <span className="matrix-corner" />
            {matrixNodes.map((node, index) => (
              <span
                className="matrix-column-label"
                key={`column-${node.id}`}
                title={node.label}
              >
                {index + 1}
              </span>
            ))}
            {matrixNodes.flatMap((rowNode, rowIndex) => [
              <span className="matrix-row-label" key={`row-${rowNode.id}`}>
                <b>{rowIndex + 1}</b>
                {rowNode.label}
              </span>,
              ...matrixNodes.map((columnNode) => {
                const relations = pairEdges.get(unorderedPairKey(rowNode.id, columnNode.id)) ?? [];
                return (
                  <button
                    type="button"
                    className={relations.length ? "has-relation" : ""}
                    key={`${rowNode.id}-${columnNode.id}`}
                    aria-label={`${rowNode.label} and ${columnNode.label}: ${relations.length} relations`}
                    title={relations.map((edge) => edge.label).join(", ")}
                    onClick={() => onSelectNodes([rowNode.id, columnNode.id])}
                  >
                    {relations.length || ""}
                  </button>
                );
              }),
            ])}
          </div>
        </div>
      )}

      {viewMode === "timeline" && (
        <div className="timeline-shell">
          {timelineEvents.length ? (
            <>
              <p className="view-note">{timelineEvents.length} dated links, oldest first{timelineEvents.length > 80 ? " · showing the first 80" : ""}</p>
              {timelineEvents.slice(0, 80).map((event) => {
                return (
                  <article
                    className="timeline-event"
                    key={event.edge.id}
                  >
                    <time dateTime={event.date.toISOString()}>{event.date.toLocaleDateString(undefined, { timeZone: "UTC" })}</time>
                    <strong>{event.source.label}</strong>
                    <span>{event.edge.label}</span>
                  </article>
                );
              })}
            </>
          ) : (
            <div className="data-empty">
              <h4>No dates are loaded yet</h4>
              <p>
                Load statements with date values (xsd:date, xsd:dateTime or xsd:gYear), for example by expanding a
                node or running a query.
              </p>
            </div>
          )}
        </div>
      )}

      {viewMode === "map" && (
        <div className="map-shell">
          {places.length ? (
            <>
              <iframe
                title={places.length === 1 ? `Map of ${places[0].node.label}` : `Map of ${places.length} places`}
                loading="lazy"
                src={mapEmbedUrl(places)}
              />
              <div className="map-locations">
                {places.map((place) => (
                  <button key={place.node.id} type="button" onClick={() => onShowInGraph(place.node.id)}>
                    <strong>{place.node.label}</strong>
                    <span>
                      {place.latitude.toFixed(4)}, {place.longitude.toFixed(4)}
                    </span>
                  </button>
                ))}
              </div>
            </>
          ) : (
            <div className="data-empty">
              <h4>No places are loaded yet</h4>
              <p>Places come from WKT points or from geo:lat and geo:long (or schema:latitude and schema:longitude) values.</p>
            </div>
          )}
        </div>
      )}

      {viewMode === "chart" && (
        <div className="chart-shell">
          {numericSeries.length ? (
            <div className="chart-series" role="group" aria-label="What the chart shows">
              {numericSeries.map((entry) => (
                <button
                  key={entry.predicate}
                  type="button"
                  aria-pressed={series?.predicate === entry.predicate}
                  title={entry.predicate}
                  onClick={() => setChosenSeries(entry.predicate)}
                >
                  {entry.label} <small>{entry.values.length}</small>
                </button>
              ))}
              <button type="button" aria-pressed={!series} onClick={() => setChosenSeries(PREDICATE_CHART)}>
                Relations
              </button>
            </div>
          ) : null}
          {(series
            ? numericHistogram.map((bin) => ({
                label: `${bin.minimum.toLocaleString(undefined, {
                  maximumFractionDigits: 2,
                })} – ${bin.maximum.toLocaleString(undefined, {
                  maximumFractionDigits: 2,
                })}`,
                count: bin.count,
              }))
            : predicateChart
          ).map((item, index, values) => (
              <div className="chart-row" key={`${item.label}-${index}`}>
                <span>{item.label}</span>
                <i
                  style={{
                    width: `${
                      (item.count /
                        Math.max(
                          ...values.map((value) => value.count),
                          1,
                        )) *
                      100
                    }%`,
                  }}
                />
                <strong>{item.count}</strong>
              </div>
            ))}
        </div>
      )}
    </section>
  );
}
